const D = { beams:9, spread:.6, energy:.7, hue:330, speed:1, density:.5, scale:1, x:.5, y:.5, sway:.6, style:'neon', act:'fan', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const neon=st==='neon',mono=st==='mono',prism=st==='prism',sheet=st==='sheet',grid=st==='grid';
const en=P.energy*(0.5+0.7*K.intensity);

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

// terminate a ray on the canvas rectangle
function hit(ox,oy,dx,dy){
  let t=Infinity;
  if(dy>1e-4){ const tb=(Hh-oy)/dy; if(tb>0)t=Math.min(t,tb); }
  if(dy<-1e-4){ const tt=(0-oy)/dy; if(tt>0)t=Math.min(t,tt); }
  if(dx>1e-4){ const tr=(W-ox)/dx; if(tr>0)t=Math.min(t,tr); }
  if(dx<-1e-4){ const tl=(0-ox)/dx; if(tl>0)t=Math.min(t,tl); }
  if(!isFinite(t))t=u; return [ox+dx*t, oy+dy*t];
}

const nB=Math.max(1,Math.round(clp(P.beams,1,22)));
const sec=Math.floor(K.section);
const pat=md(sec,4);
const treb=0.55+0.9*A.treble;
const bright=clp((0.4+0.6*Math.max(K.swell,0)*0.6+0.5*K.pulse)*(0.6+en)*treb,0,1.5);
const spreadAng=lrp(0.15,1.15,clp(P.spread,0,1))*(pat===2?(0.5+0.5*Math.abs(Math.sin(K.t*0.5))):1);
const swAmp=0.5*P.sway;
const haze=Math.round(lrp(0,2,clp(P.density,0,1)));
const actCross=P.act==='cross', actScan=P.act==='scan';

// emitters: top-left & top-right corners (nudged by x)
const emit=[ {ox:W*(0.04+ (P.x-0.5)*0.1), oy:-u*0.02, base:0.55, dir:1},
             {ox:W*(0.96+ (P.x-0.5)*0.1), oy:-u*0.02, base:-0.55, dir:-1} ];

blendMode(ADD);
for(let ei=0; ei<emit.length; ei++){
  const E=emit[ei];
  // fan center angle sweeps continuously (real-time), section changes speed/shape
  const swp = Math.sin(K.t*(0.35+pat*0.18)*P.speed + ei*2.1)*swAmp
            + (pat===1? Math.sin(K.t*0.9*P.speed)*0.4 : 0);
  const centerA = E.base*(actCross?-1:1) + swp;
  for(let b=0;b<nB;b++){
    const f = nB<2?0.5:b/(nB-1);
    let a = centerA + (f-0.5)*spreadAng;
    if(pat===3) a += Math.sin(K.t*1.4*P.speed + b*0.8)*0.12;       // scissor shimmer
    if(actScan) a = centerA + (Math.sin(K.t*0.8*P.speed)*0.5)*spreadAng*0.2 + (f-0.5)*0.04;
    const dx=Math.sin(a), dy=Math.cos(a);
    const [hx,hy]=hit(E.ox,E.oy,dx,dy);
    const hh = prism? md(H + f*140 + ei*20, 360) : mono? md(H,360) : md(H + (f-0.5)*36 + ei*14, 360);
    const sat = mono? 22 : 92;
    const flick = 0.7+0.3*Math.sin(K.t*7+b*1.3+ei);
    const bA = bright*flick;
    if(grid){
      // abstract: sample dots along the beam path (dot-lattice scan)
      const dots=10;
      noStroke();
      for(let d=1; d<=dots; d++){ const t=d/dots; const px=lrp(E.ox,hx,t), py=lrp(E.oy,hy,t); fill(hh,sat,100, clp(30*bA*(1-t*0.3),0,34)); ellipse(px,py, u*0.008*(0.6+treb*0.5), u*0.008); }
    } else if(sheet){
      // volumetric sheet — wide faint band + core
      strokeCap(SQUARE);
      stroke(hh,sat,100, clp(9*bA,0,20)); strokeWeight(Math.max(3,u*0.012)); line(E.ox,E.oy,hx,hy);
      stroke(hh,lrp(sat,40,0.4),100, clp(22*bA,0,34)); strokeWeight(Math.max(1.5,u*0.004)); line(E.ox,E.oy,hx,hy);
    } else {
      // neon / mono / prism — thin bright core + soft halo
      for(let l=haze;l>0;l--){ const t=l/haze; stroke(hh,sat,100, clp(8*bA,0,16)); strokeWeight(Math.max(2,u*0.006*(1+t))); line(E.ox,E.oy,hx,hy); }
      stroke(md(hh+ (prism?0:6),360), lrp(sat,55,0.3), 100, clp(30*bA,0,34)); strokeWeight(Math.max(1,u*0.0018)); line(E.ox,E.oy,hx,hy);
      stroke(hh,20,100, clp(34*bA,0,34)); strokeWeight(Math.max(0.6,u*0.0008)); line(E.ox,E.oy,hx,hy);
      // terminal spark where the beam lands
      noStroke(); fill(hh,40,100, clp(40*bA,0,45)); ellipse(hx,hy, u*0.012*(0.6+A.treble*1.5), u*0.012);
    }
  }
  // emitter head glow
  noStroke(); fill(md(H+ei*14,360), mono?22:60, 100, clp(38*bright,0,40)); ellipse(E.ox,E.oy, u*0.05, u*0.05);
}
blendMode(BLEND);
strokeCap(ROUND);
